insert into public.puzzles (id, owner_id, size, setup, answers, title, prompt, explanation, difficulty) values
 ('e01', null, 9, '{"rows":[".........",".........",".........","...XX....","..XOTX...","...X.....",".........",".........","........."],"toPlay":"B","refutation":"Pas encore. Les deux pierres blanches se touchent : elles forment un groupe et partagent leurs libertés. Un seul point vide les touche encore."}', array['E4'], 'Deux pierres au centre', 'Capture tout de suite les deux pierres blanches.', 'Bravo ! Les libertés d''un groupe sont les points vides qui le touchent. Ces deux pierres n''en avaient plus qu''une, E4 : elles étaient en atari. En E4, tu les captures toutes les deux.', 350),
 ('e02', null, 9, '{"rows":[".........",".........",".........",".........",".........",".........",".........","..XX.....",".XOTOX..."],"toPlay":"B","refutation":"Pas encore. Les trois pierres blanches du bord forment un seul groupe. Fais-en le tour : il ne lui reste qu''un point vide."}', array['E2'], 'Trois pierres au bord', 'Capture tout de suite les trois pierres blanches du bord.', 'Exact ! Les pierres qui se touchent forment un groupe, et ses libertés sont les points vides qui le touchent. Ici, il n''en restait qu''une, E2 : le groupe était en atari. Tu prends trois pierres d''un coup.', 380),
 ('e03', null, 9, '{"rows":[".........",".........","...XTX...","...OSO...",".........",".........",".........",".........","........."],"toPlay":"B","refutation":"Pas celle-là. Ta pierre marquée est en atari, mais la pierre blanche qui la serre par le haut l''est aussi : elle n''a plus qu''un point vide, au-dessus d''elle."}', array['E8'], 'Prends celle qui te serre', 'Ta pierre marquée est en atari. Capture tout de suite la pierre blanche marquée.', 'Bien joué ! Les libertés sont les points vides à côté d''une pierre. La pierre blanche E7 n''en avait qu''une, E8 : elle était en atari. En la capturant, ta pierre E6 retrouve de l''air : deux libertés, E7 et E5.', 420),
 ('e04', null, 9, '{"rows":[".........",".........",".........",".........",".........",".........",".........","..XOO....","..TSS.O.."],"toPlay":"B","refutation":"Pas tout à fait. Tes deux pierres marquées n''ont qu''une liberté, F1. Si tu t''y allonges, il ne leur reste que F2 : toujours en atari. La pierre blanche C1, elle, n''a plus qu''un point vide."}', array['B1'], 'Sauve-toi par la gauche', 'Tes pierres marquées sont en atari. Capture tout de suite la pierre blanche marquée pour les sauver.', 'Excellent ! Les libertés sont les points vides à côté d''un groupe. La pierre blanche C1 n''en avait qu''une, B1 : elle était en atari, et tu la captures. Tes pierres D1 et E1 ont maintenant deux libertés, C1 et F1. En F1, elles seraient restées en atari.', 480),
 ('e05', null, 9, '{"rows":[".........",".........",".........",".........","....X....","...XT.X..",".....X...",".........","........."],"toPlay":"B","refutation":"Pas celle-là. Après F4, Blanc s''allonge en E3, vers le bas : il retrouve deux libertés, D3 et E2, et tu ne peux plus le capturer à temps. Pousse-le vers tes pierres F3 et G4."}', array['E3'], 'Vers tes deux pierres', 'Mets la pierre marquée en atari en la poussant vers tes pierres, puis capture-la.', 'Bravo ! Mettre en atari, c''est ne laisser qu''une liberté (un point vide à côté) à une pierre. Après E3, il ne lui reste que F4. Si Blanc s''y allonge, tes pierres F3 et G4 l''attendent : son groupe n''a toujours qu''une liberté, F5, et tu le captures.', 520),
 ('e06', null, 9, '{"rows":[".........",".........",".........",".........",".........",".........",".........","...X.X...","..XTO...."],"toPlay":"B","refutation":"Pas encore. Le groupe blanc a deux libertés, E2 et F1. Retire-lui-en une tout de suite : tes pierres D2 et F2 font le reste."}', array['E2','F1'], 'Deux libertés sur le bord', 'Capture les deux pierres blanches du bord en deux coups.', 'Exact ! Le groupe avait deux libertés (points vides à côté de lui), E2 et F1. Tu en prends une : il est en atari. S''il s''allonge, tes pierres D2 et F2 lui bouchent la route : il reste en atari et tu le captures. Les deux mises en atari marchent.', 560),
 ('e07', null, 9, '{"rows":[".........",".........",".XX.X....",".XT.TX...",".........",".........",".........",".........","........."],"toPlay":"B","refutation":"Pas tout à fait. Si tu ne menaces qu''une pierre, Blanc joue D6 : il relie ses deux pierres et leur donne assez de libertés. Joue ce point avant lui."}', array['D6'], 'Double atari au centre', 'Un seul coup met les deux pierres marquées en atari. Joue-le, puis capture.', 'Bravo ! Chaque pierre blanche avait deux libertés (points vides à côté d''elle), dont D6 en commun. En D6, il ne leur en reste qu''une chacune, C5 et E5 : c''est un double atari. Blanc en sauve une, tu prends l''autre.', 600),
 ('e08', null, 9, '{"rows":[".........",".........",".........",".........",".X.......",".TX......",".........",".........","........."],"toPlay":"B","refutation":"Pas celle-là. Après A4, Blanc s''allonge en B3, vers l''intérieur : il a trois libertés et s''échappe. Pousse-le plutôt contre le bord."}', array['B3'], 'Contre le bord gauche', 'Mets la pierre marquée en atari du bon côté, puis capture-la.', 'Exact ! Après B3, la pierre n''a plus qu''une liberté (un point vide à côté), A4 : elle est en atari. Si Blanc s''allonge en A4, son groupe n''a que deux libertés sur le bord, A3 et A5. Tu en prends une, il s''allonge, et tu le captures au coup suivant. Le bord ne laisse pas de place pour fuir.', 630),
 ('e09', null, 9, '{"rows":[".........",".........",".........",".........",".........",".........","...XX....","..XTO....","........."],"toPlay":"B","refutation":"Pas encore. Le groupe blanc a trois libertés : D1, E1 et F2. Seule F2 mène vers le centre : ferme-la d''abord, le bord fera le reste."}', array['F2'], 'Ferme la sortie', 'Capture les deux pierres blanches en trois coups au plus.', 'Superbe ! Le groupe avait trois libertés (points vides à côté de lui), D1, E1 et F2. En F2, tu fermes la seule sortie vers le centre. Il ne lui reste que D1 et E1, sur le bord : s''il s''allonge, chaque fois tu le remets en atari (une seule liberté), jusqu''à le capturer.', 680)
